                    "source": {
                        "type": "string",
                        "description": "Source of the recipe"
                    },
                    "steps": {
                        "type": "string",
                        "description": "Instructions to make the drink"
                    }
                },
                "required": [
                    "id",
                    "default",
                    "name",
                    "hidden",
                    "favorite",
                    "details",
                    "ingredients",
                    "steps"
                ]
            }
        }
    }
}

